function updatePayment(){applyPaymentAvailability();const t=totals(),deliveryToggle=$("#delivery-enabled"),deliveryLabel=$("#delivery-fee-label"),deliveryRow=$("#checkout-delivery-row");if(deliveryLabel)deliveryLabel.classList.toggle("hidden",!deliveryToggle?.checked);if(deliveryRow)deliveryRow.classList.toggle("hidden",!deliveryToggle?.checked);if($("#checkout-delivery-fee"))$("#checkout-delivery-fee").textContent=money(t.deliveryFee);const cash=$("#payment-method").value==="Tunai",received=Number($("#cash-received").value)||0;$("#checkout-cash-label").classList.toggle("hidden",!cash);$("#checkout-cash-change").textContent=money(Math.max(0,received-t.total));$("#checkout-btn").disabled=!cart.length||!!data.outletClosed||checkoutBusy;$("#checkout-screen-btn").disabled=!cart.length||!requireCheckout(cash,received,t.total)||!!data.outletClosed||checkoutBusy;const panel=$("#cart-panel");if(panel){panel.classList.toggle("cart-has-items",cart.length>0);if(cart.length){$("#sheet-toggle-text").textContent="Buka pembayaran →"}else{panel.classList.remove("sheet-expanded");$("#cart-sheet-toggle")?.setAttribute("aria-expanded","false");$("#sheet-toggle-text").textContent="Pilih menu untuk mulai"}}}
