 x.textAlign='center';x.fillStyle='#38251e';x.font='bold 24px Arial';x.fillText(String(data.settings.outlet||'OR!ON CORNDOG'),width/2,y);y+=30;x.font='18px Arial';if(data.settings.address){x.fillText(String(data.settings.address),width/2,y);y+=25}if(data.settings.phone){x.fillText(String(data.settings.phone),width/2,y);y+=25}
